import{_ as t,C as i,o as r,c as s,aj as a,E as u}from"./chunks/framework.D04Qc2jV.js";const b=JSON.parse('{"title":"Schreiben, Marketing und Content","description":"","frontmatter":{"title":"Schreiben, Marketing und Content"},"headers":[],"relativePath":"kapitel/06-schreiben-marketing-content.md","filePath":"kapitel/06-schreiben-marketing-content.md"}'),l={name:"kapitel/06-schreiben-marketing-content.md"};function d(h,e,o,g,c,m){const n=i("FeedbackForm");return r(),s("div",null,[e[0]||(e[0]=a('<h1 id="kapitel-6-schreiben-marketing-und-content" tabindex="-1">Kapitel 6: Schreiben, Marketing und Content <a class="header-anchor" href="#kapitel-6-schreiben-marketing-und-content" aria-label="Permalink to &quot;Kapitel 6: Schreiben, Marketing und Content&quot;">​</a></h1><h2 id="ein-redaktionssystem-fur-einzelunternehmer" tabindex="-1">Ein Redaktionssystem für Einzelunternehmer <a class="header-anchor" href="#ein-redaktionssystem-fur-einzelunternehmer" aria-label="Permalink to &quot;Ein Redaktionssystem für Einzelunternehmer&quot;">​</a></h2><p>Sie haben eine Idee für einen Blogartikel. Die Idee ist gut. Aber zwischen der Idee und dem fertigen Artikel liegen: Recherche, Gliederung, erster Entwurf, Überarbeitung, Stilkorrektur, SEO-Prüfung, Formatierung und Veröffentlichung. Jeder dieser Schritte ist lösbar. Zusammen kosten sie so viel Zeit, dass viele Selbständige Artikel gar nicht erst schreiben, obwohl sie eigentlich wüssten, was sie zu sagen haben.</p><p>Dieses Kapitel zeigt, wie ein Agent einen Großteil dieser Schritte übernimmt, ohne dabei Ihren Stil zu ersetzen oder Ihre Stimme zu imitieren. Das Ziel ist ein pragmatisches Redaktionssystem, das regelmäßig funktioniert und dabei immer Sie als Autor im Mittelpunkt lässt.</p><h2 id="warum-content-fur-selbstandige-so-schwer-ist" tabindex="-1">Warum Content für Selbständige so schwer ist <a class="header-anchor" href="#warum-content-fur-selbstandige-so-schwer-ist" aria-label="Permalink to &quot;Warum Content für Selbständige so schwer ist&quot;">​</a></h2><p>Content, also Artikel, Newsletter, LinkedIn-Beiträge, Website-Texte, ist für viele Selbständige gleichzeitig wichtig und lästig. Wichtig, weil er Sichtbarkeit erzeugt, Vertrauen aufbaut und potenzielle Kunden anzieht. Lästig, weil er Zeit kostet, die eigentlich für Kundenprojekte da wäre, und weil er eine besondere Art von Aufmerksamkeit erfordert, die sich nicht einfach in die Lücken zwischen anderen Aufgaben schieben lässt.</p><p>Das Ergebnis ist bekannt: Der Redaktionsplan liegt im Entwurf, der letzte Artikel ist von vor drei Monaten, der Newsletter-Eintrag bleibt ungeschickt, weil der Entwurf irgendwie nie fertig geworden ist.</p><p>KI-Agenten können diesen Teufelskreis aufbrechen, aber nicht, indem sie einfach Artikel produzieren. Sie können ihn aufbrechen, indem sie jeden Teilschritt des Content-Prozesses schneller und leichter machen, sodass Sie sich auf die Teile konzentrieren können, die wirklich Ihren Beitrag brauchen: die Perspektive, das Urteil, die persönliche Stimme.</p><h2 id="die-grundunterscheidung-stimme-und-struktur" tabindex="-1">Die Grundunterscheidung: Stimme und Struktur <a class="header-anchor" href="#die-grundunterscheidung-stimme-und-struktur" aria-label="Permalink to &quot;Die Grundunterscheidung: Stimme und Struktur&quot;">​</a></h2><p>Bevor wir in den konkreten Workflow einsteigen, lohnt sich eine wichtige Unterscheidung. Im Content gibt es zwei Ebenen: Stimme und Struktur.</p><p>Struktur ist alles, was ein Text braucht, um lesbar und logisch zu sein: Gliederung, Absätze, Übergänge, Überschriften, einheitliche Formatierung, Quellenangaben. Struktur lässt sich erlernen, dokumentieren und weitgehend automatisieren.</p><p>Stimme ist das, was einen Text unverwechselbar macht: die Haltung, die Perspektive, die Erfahrungen, der Humor oder Ernst, die Formulierungsgewohnheiten, die Fragen, die Sie stellen, und die Art, wie Sie Antworten geben. Stimme kann nicht automatisiert werden. Sie kann von einem Agenten imitiert werden, wenn Sie ihm genug Beispiele geben, aber sie entsteht nicht durch Automatisierung. Sie entsteht durch Sie.</p><p>Ein gut aufgebautes Redaktionssystem mit KI-Unterstützung lässt den Agenten die Struktur übernehmen und schützt die Stimme. Das klingt einfach, erfordert aber eine bewusste Entscheidung an jedem Schritt des Prozesses: Wo ist mein Beitrag nötig? Wo kann ich loslassen?</p><h2 id="das-stilprofil-die-grundlage-fur-gute-texte" tabindex="-1">Das Stilprofil: Die Grundlage für gute Texte <a class="header-anchor" href="#das-stilprofil-die-grundlage-fur-gute-texte" aria-label="Permalink to &quot;Das Stilprofil: Die Grundlage für gute Texte&quot;">​</a></h2><p>Bevor Sie einen Agenten für Content-Arbeit nutzen, lohnt es sich, ein Stilprofil anzulegen. Ein Stilprofil ist eine schriftliche Beschreibung Ihres Schreibstils, die der Agent als Referenz nutzt.</p><p>Ein einfaches Stilprofil enthält: den bevorzugten Ton, zum Beispiel direkt und sachlich oder nahbar und persönlich, die typische Satzlänge, die Zielgruppe und ihr Vorwissen, Formulierungen und Wörter, die Sie bewusst vermeiden, Formulierungen und Strukturen, die Ihnen wichtig sind, und konkrete Beispiele aus Ihren besten Texten.</p><p>Das Stilprofil kommt in die CLAUDE.md oder AGENTS.md des Agenten, der Texte für Sie schreibt. Beim ersten Einsatz werden Sie merken, dass der Agent gut formuliert, aber nicht wirklich Ihr Schreibstil ist. Das ist normal. Mit jeder Iteration, bei der Sie den Agenten korrigieren und das Stilprofil anpassen, wird er besser.</p><p>Ein Hinweis zur Erwartungshaltung: Selbst ein sehr gut konfigurierter Agent schreibt keine Texte, die Sie ohne Überarbeitung veröffentlichen sollten. Er liefert 70 bis 80 Prozent des Weges. Die restlichen 20 bis 30 Prozent sind Ihr Beitrag. Das ist deutlich weniger Arbeit als vorher, aber es bleibt Ihre Arbeit.</p><h2 id="der-content-workflow-vom-thema-zum-fertigen-text" tabindex="-1">Der Content-Workflow: Vom Thema zum fertigen Text <a class="header-anchor" href="#der-content-workflow-vom-thema-zum-fertigen-text" aria-label="Permalink to &quot;Der Content-Workflow: Vom Thema zum fertigen Text&quot;">​</a></h2><p>Ein produktiver Content-Workflow mit KI-Unterstützung besteht aus sechs Schritten.</p><p>Der erste Schritt ist das Ideenmanagement. Gute Themen kommen unregelmäßig: beim Duschen, im Kundengespräch, beim Lesen eines Artikels. Ein Agent kann eine Ideendatei pflegen, Ideen nach Priorität und Relevanz ordnen und Ihnen wöchentlich einen Vorschlag machen, welche Idee als nächstes bearbeitet werden sollte. Das sorgt dafür, dass keine Idee verloren geht und dass die Content-Planung eine Grundlage hat.</p><p>Der zweite Schritt ist die Themenrecherche. Sobald eine Idee ausgewählt ist, recherchiert der Agent den Themenbereich: Was wird bereits zu diesem Thema geschrieben? Welche Quellen sind relevant? Was fehlt in der bisherigen Berichterstattung, was Ihr Artikel leisten könnte? Das Ergebnis ist ein Recherchebriefing nach dem Schema aus Kapitel 5: Fakten, Quellen, Unsicherheiten.</p><p>Der dritte Schritt ist die Gliederung. Auf Basis des Recherchebriefings erstellt der Agent eine erste Gliederung: Kernthese, Abschnitte, Argumente, Beispiele. Sie überprüfen die Gliederung, korrigieren die Struktur und fügen eigene Perspektiven hinzu, die der Agent nicht haben kann, zum Beispiel Erfahrungen aus einem konkreten Kundenprojekt oder eine persönliche Haltung zu einem umstrittenen Punkt.</p><p>Der vierte Schritt ist der erste Entwurf. Mit der geprüften Gliederung und dem Stilprofil als Grundlage schreibt der Agent einen vollständigen Erstentwurf. Dieser Entwurf ist immer ein Ausgangspunkt, keine finale Version. Er enthält die Struktur, füllt die Argumente aus und liefert eine lesbare Form, aber er enthält noch nicht Ihre Stimme.</p><p>Der fünfte Schritt ist die Überarbeitung. Sie lesen den Entwurf durch, streichen, was nicht stimmt, fügen eigene Formulierungen und Beispiele ein, korrigieren den Ton und überarbeiten Stellen, die zu generisch klingen. Dann können Sie den überarbeiteten Entwurf zurück an den Agenten geben und ihn bitten, Stilinkonsistenzen zu glätten, Wiederholungen zu entfernen und die Übergänge zu verbessern.</p><p>Der sechste Schritt ist die Finalisierung. Der Agent prüft den Text auf formale Punkte: Rechtschreibung, Grammatik, konsistente Formatierung, korrekte Verlinkungen und, wenn relevant, grundlegende SEO-Aspekte wie das Vorhandensein wichtiger Begriffe. Sie lesen die finale Version noch einmal und geben sie frei.</p><p>Dieser sechsstufige Prozess klingt lang. In der Praxis dauern die ersten drei Schritte bei einem Agenten oft zusammen weniger als 15 Minuten. Der eigentliche Zeitaufwand liegt beim fünften Schritt: Ihrer Überarbeitung. Aber auch der ist deutlich kürzer als das Schreiben eines Artikels von null.</p><h2 id="newsletter-das-unterschatzte-format-fur-selbstandige" tabindex="-1">Newsletter: Das unterschätzte Format für Selbständige <a class="header-anchor" href="#newsletter-das-unterschatzte-format-fur-selbstandige" aria-label="Permalink to &quot;Newsletter: Das unterschätzte Format für Selbständige&quot;">​</a></h2><p>Newsletter sind für viele Selbständige das wirkungsvollste Content-Format, weil sie eine direkte Verbindung zu Menschen aufbauen, die bereits Interesse gezeigt haben. Gleichzeitig sind sie aufwändig, weil sie regelmäßig erscheinen müssen, um ihren Wert zu entfalten.</p><p>Ein Agent kann den Newsletter-Prozess erheblich vereinfachen. Die Grundstruktur eines guten Newsletters, also Einleitung mit aktuellem Aufhänger, Hauptthema mit konkretem Nutzen für den Leser, Empfehlung oder Ressource der Woche, kurzer Ausblick auf das nächste Thema, lässt sich als Skill oder Vorlage speichern. Der Agent befüllt diese Struktur mit dem aktuellen Thema, zieht relevante Informationen aus dem Recherchebriefing und erstellt einen Erstentwurf, den Sie überarbeiten und dann versenden.</p><p>Besonders nützlich ist dabei die Konsistenz des Agenten. Ein Mensch, der erschöpft ist, schreibt einen anderen Newsletter als ein Mensch, der gut ausgeruht ist. Ein Agent schreibt immer nach derselben Struktur, was dem Leser Orientierung gibt, auch wenn Ihre Überarbeitung von Woche zu Woche unterschiedlich stark ausfällt.</p><h2 id="linkedin-und-kurze-formate-schnell-und-wirkungsvoll" tabindex="-1">LinkedIn und kurze Formate: Schnell und wirkungsvoll <a class="header-anchor" href="#linkedin-und-kurze-formate-schnell-und-wirkungsvoll" aria-label="Permalink to &quot;LinkedIn und kurze Formate: Schnell und wirkungsvoll&quot;">​</a></h2><p>Kurze Formate wie LinkedIn-Beiträge, kurze Artikel oder Social-Media-Posts profitieren ebenfalls von Agentenunterstützung, aber auf eine andere Weise als lange Artikel.</p><p>Bei kurzen Formaten liegt der Wert des Agenten weniger in der Recherche als in der Variantenbildung. Sie haben eine Kernbotschaft. Der Agent formuliert fünf verschiedene Versionen davon: eine persönliche, eine provokante, eine sachliche, eine narrative, eine listenbasierte. Sie wählen die Version, die Ihnen am besten gefällt, und passen sie an Ihren Stil an.</p><p>Das ist schneller als selbst mit dem leeren Cursor zu sitzen und darauf zu warten, dass die richtige Formulierung kommt. Und es liefert oft Versionen, die Sie selbst so nicht geschrieben hätten, weil der Agent Winkel einnimmt, die Sie aus Gewohnheit ausgelassen hätten.</p><h2 id="website-texte-strukturiert-und-zielgruppenorientiert" tabindex="-1">Website-Texte: Strukturiert und zielgruppenorientiert <a class="header-anchor" href="#website-texte-strukturiert-und-zielgruppenorientiert" aria-label="Permalink to &quot;Website-Texte: Strukturiert und zielgruppenorientiert&quot;">​</a></h2><p>Website-Texte sind eine eigene Kategorie, weil sie eine besondere Funktion haben: Sie sollen nicht nur informieren, sondern eine Entscheidung herbeiführen. Ein Besucher soll nach dem Lesen einer Leistungsseite besser verstehen, warum er mit Ihnen zusammenarbeiten sollte, als vorher.</p><p>Agenten können bei Website-Texten in zwei Bereichen helfen. Erstens bei der Strukturanalyse: Der Agent prüft einen bestehenden Website-Text auf Klarheit, Struktur und fehlende Informationen aus Kundenperspektive. Was beantwortet der Text nicht, was ein potenzieller Kunde wahrscheinlich fragen würde? Zweitens bei der Überarbeitungsvorlage: Der Agent erstellt eine überarbeitete Version mit klarerer Struktur, konkreteren Versprechen und besserem Lesefluss. Sie entscheiden, was davon tatsächlich auf die Website kommt.</p><p>Eine wichtige Einschränkung: Website-Texte, die vollständig von einem Agenten ohne ausreichende Überarbeitung produziert wurden, klingen oft generisch. Sie enthalten alle richtigen Elemente, aber es fehlt die Spezifität, die Vertrauen erzeugt. Ein Beispiel: &quot;Ich begleite Unternehmen auf dem Weg zur digitalen Transformation&quot; klingt wie jeder zweite Berater. &quot;Ich helfe kleinen Beratungsunternehmen, ihren ersten strukturierten Content-Workflow aufzubauen, der ohne wöchentlichen Agentenaufwand funktioniert&quot; klingt nach jemandem, der weiß, was er tut. Der Agent kann die Struktur liefern. Die Spezifität müssen Sie einbringen.</p><h2 id="content-planung-das-redaktionskalender-setup" tabindex="-1">Content-Planung: Das Redaktionskalender-Setup <a class="header-anchor" href="#content-planung-das-redaktionskalender-setup" aria-label="Permalink to &quot;Content-Planung: Das Redaktionskalender-Setup&quot;">​</a></h2><p>Ein vollständiges Redaktionssystem für Selbständige sollte auch eine einfache Content-Planung enthalten.</p><p>Die Grundidee ist simpel: Sie haben eine Datei, in der Themen, Status und Erscheinungstermine festgehalten sind. Der Agent prüft diese Datei regelmäßig, erinnert Sie an anstehende Veröffentlichungen, schlägt neue Themen auf Basis aktueller Entwicklungen in Ihrem Bereich vor und aktualisiert den Status, wenn Texte fertiggestellt werden.</p><p>Das klingt nach wenig, hat aber eine wichtige psychologische Wirkung: Content ist plötzlich kein amorphes Aufgabenfeld mehr, das irgendwo wartet. Es ist eine strukturierte Liste mit klarem Status, nächsten Schritten und einem System, das regelmäßig darauf hinweist, was als nächstes dran ist.</p><p>Praxishinweis aus dem aktuellen Stand von 2026: KI-Agenten im Content-Bereich sind 2026 dann produktiv, wenn sie als Vorschlagsmaschine und Strukturhilfe eingesetzt werden und ein Mensch jeden Schritt prüft. Vollautomatische Content-Produktion ohne menschliche Freigabe ist zuverlässigkeitstechnisch noch nicht dort, wo man blind vertrauen kann. Die Stärke liegt im Human-in-the-Loop-Prinzip: Agent produziert Entwurf, Mensch entscheidet. Damit lassen sich 70 bis 80 Prozent Zeitersparnis erzielen bei einer Fehlerquote, die nahe an rein menschlicher Arbeit liegt.</p>',44)),u(n)])}const f=t(l,[["render",d]]);export{b as __pageData,f as default};
